import pathlib,json,hashlib,importlib.util,collections,numpy as np,math
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
SRC=R/'y06_r3_bear_retest_research_v2.py'
sp=importlib.util.spec_from_file_location('r3',SRC);r3=importlib.util.module_from_spec(sp);sp.loader.exec_module(r3)
bt=r3.bt;H=bt.H;M=bt.M
P=R/'Y06_R10_SEPARATED_MARKET_PROTOCOL_20261127.json';O=R/'Y06_R10_SEPARATED_MARKET_RESULTS_20261127.json'
assert not P.exists() and not O.exists()
p={'status':'EXPLORATORY_RESEARCH_ONLY','prior_sha256':hashlib.sha256((R/'Y06_R9_FACTOR_DECOMPOSITION_RESULTS_20261127.json').read_bytes()).hexdigest(),'source_sha256':hashlib.sha256(SRC.read_bytes()).hexdigest(),'market':'At UTC 0/6/12/18 market state uses BTC fully closed trailing24/72h and >=8 assets with 25 finite H1 closes; breadth >=60% down for BEAR or <=40% down for BULL. Market breadth independent of M5 tradability.','asset':'Only original R3 individual QA-passing symbols eligible for entries. 72h or 168h beta and residual std calculated on continuous past H1. At least 2 eligible to rank. No future label filtering.','arms':{'BEAR_REV168':'BEAR SHORT highest standardized residual24h >=0.5 using beta168','BEAR_MOM168':'BEAR SHORT lowest standardized residual24h <=-0.5 using beta168','BEAR_REV72':'BEAR SHORT highest standardized residual24h >=0.5 using beta72','BEAR_MOM72':'BEAR SHORT lowest standardized residual24h <=-0.5 using beta72','BEAR_REV_FADE72':'BEAR SHORT residual24h>=0.5, latest residual6h<0, rank residual24h','BEAR_BTC_REV72':'BTC24/72 down regardless of breadth, SHORT highest residual24h>=0.5','BULL_REV72':'BULL LONG lowest residual24h<=-0.5','BULL_MOM72':'BULL LONG highest residual24h>=0.5','MIXED_REV72':'MIXED choose largest absolute residual24h>=1.5 opposite side'},'exit':'12/24/48h fixed, STOP8 gap adverse, 10/30bps, Gross .30 per position, original 2 slot 12h cooldown. All source periods inspected; no funding; no production.','controls':'32 same-time randomized other QA-eligible symbols for each arm with at least 2 profitable splits, plus both REV/MOM 72 24h and 48h. Exact same side/horizon/portfolio. Diagnostic matched cohorts. No independence claims.'}
P.write_text(json.dumps(p,indent=2),encoding='utf8')
btc,_=bt.data('BTC','1h');hs={};ms={};qa={}
for sym in bt.SYMS[1:]:
 h,_=bt.data(sym,'1h');m,_=bt.data(sym,'5m');hs[sym]=h;ms[sym]=m;qa[sym]=r3.prepare_qa(h,m)[0];print('LOAD',sym,flush=True)
def perof(t):return next((k for k,(a,b) in bt.PERIODS.items() if a<=t<b),None)
def endof(per):return bt.PERIODS[per][1] if per!='FORWARD_INSPECTED' else bt.T('2026-11-26T00:00:00Z')
def trade(x,side,hr):
 m=ms[x['symbol']];k=(x['entryTs']-bt.MS)//M;j=k+hr*12
 if k<0 or j>=len(m) or not np.isfinite(m[k:j+1,:4]).all():return None
 ep=float(m[k,0]);stop=ep*(1-side*.08);hit=np.flatnonzero(m[k:j,2]<=stop) if side==1 else np.flatnonzero(m[k:j,1]>=stop)
 et=bt.MS+j*M;xp=float(m[j,0]);reason='TIME'+str(hr)
 if len(hit):
  q=k+int(hit[0]);et=bt.MS+(q+1)*M;xp=float(min(m[q,0],stop) if side==1 else max(m[q,0],stop));reason='HARD_STOP8'
 if et>=endof(x['period']):return None
 return {**x,'exitTs':et,'entry':ep,'exitPrice':xp,'direction':'LONG' if side==1 else 'SHORT','rawReturn':side*(xp/ep-1),'exitReason':reason}
def compact(w):return {k:v for k,v in w.items() if k!='accepted'}
def factors(sym,i,n,b):
 h=hs[sym]
 if not qa[sym][i] or not np.isfinite(h[i-n-1:i,3]).all():return None
 a=np.diff(np.log(h[i-n-1:i,3]));var=float(np.var(b))
 if var<=1e-12:return None
 beta=float(np.clip(np.mean((a-a.mean())*(b-b.mean()))/var,0,3));res=a-beta*b;sd=float(np.std(res))
 if sd<=1e-9:return None
 return dict(symbol=sym,entryTs=bt.HS+i*H,period=perof(bt.HS+i*H),beta=beta,z24=float(res[-24:].sum()/sd/np.sqrt(24)),z6=float(res[-6:].sum()/sd/np.sqrt(6)))
signals={k:[] for k in p['arms']};snaps={};coverage=collections.defaultdict(collections.Counter);regime_diag=collections.defaultdict(list)
for i in range(220,len(btc)):
 t=bt.HS+i*H;per=perof(t)
 if not per or t%(6*H):continue
 cv=coverage[per];cv['all_snapshots']+=1
 if not np.isfinite(btc[i-73:i,3]).all():cv['btc72_missing']+=1;continue
 breadth_raw=[h[i-1,3]/h[i-25,3]-1 for h in hs.values() if np.isfinite(h[i-25:i,3]).all()]
 if len(breadth_raw)<8:cv['breadth_missing']+=1;continue
 cv['market_available']+=1
 breadth=float(np.mean(np.array(breadth_raw)<0));b=np.diff(np.log(btc[i-73:i,3]));b24=b[-24:].sum();b72=b.sum()
 bearish=b24<0 and b72<0;bullish=b24>0 and b72>0
 regime='BEAR' if bearish and breadth>=.6 else 'BULL' if bullish and breadth<=.4 else 'MIXED'
 cv['market_'+regime]+=1
 f72=[x for s in hs if (x:=factors(s,i,72,b)) is not None]
 f168=[]
 if np.isfinite(btc[i-169:i,3]).all():
  bb=np.diff(np.log(btc[i-169:i,3]));f168=[x for s in hs if (x:=factors(s,i,168,bb)) is not None]
 cv['tradable_asset_observations']+=len(f72)
 for n,ff in ((72,f72),(168,f168)):
  if len(ff)>=2:cv['eligible_'+str(n)]+=1
  if len(ff)>=8:cv['eligible8_'+str(n)]+=1
  if len(ff)<2:continue
  snaps[(t,n)]=ff
  order=sorted(ff,key=lambda x:(x['z24'],x['symbol']));lo,hi=order[0],order[-1]
  def add(arm,x,d):signals[arm].append((x,d,n))
  if regime=='BEAR':
   if hi['z24']>=.5:add('BEAR_REV'+str(n),hi,-1)
   if lo['z24']<=-.5:add('BEAR_MOM'+str(n),lo,-1)
  if n==72:
   if regime=='BEAR':
    a=[x for x in ff if x['z24']>=.5 and x['z6']<0]
    if a:add('BEAR_REV_FADE72',max(a,key=lambda x:(x['z24'],x['symbol'])),-1)
   if bearish and hi['z24']>=.5:add('BEAR_BTC_REV72',hi,-1)
   if regime=='BULL':
    if lo['z24']<=-.5:add('BULL_REV72',lo,1)
    if hi['z24']>=.5:add('BULL_MOM72',hi,1)
   if regime=='MIXED':
    v=max((lo,hi),key=lambda x:abs(x['z24']))
    if abs(v['z24'])>=1.5:add('MIXED_REV72',v,1 if v['z24']<0 else -1)
for per,c in coverage.items():print('COVERAGE',per,dict(c),flush=True)
out={};tapes={}
for arm,items in signals.items():
 for hr in (12,24,48):
  key=arm+'/'+str(hr);out[key]={};tapes[key]={}
  for per in bt.PERIODS:
   xx=[(x,d,n) for x,d,n in items if x['period']==per and x['entryTs']+hr*H<endof(per)]
   ts=[(z,n) for x,d,n in xx if (z:=trade(x,d,hr)) is not None];tapes[key][per]=ts
   wallets={str(f):compact(bt.wallet([z for z,n in ts],per,f,ms)) for f in (10,30)}
   out[key][per]={'intentions':len(xx),'unpriced':len(xx)-len(ts),'wallet':wallets,'mean_net_pct':float(100*np.mean([z['rawReturn']-.003 for z,n in ts])) if ts else None}
  v=[out[key][per]['wallet']['30'] for per in bt.PERIODS];print('BT',key,[(round(x['terminal_jpy']),round(x['max_dd_pct'],2),x['n'],round(x['win_pct'],2) if x['win_pct'] is not None else None) for x in v],flush=True)
rng=np.random.default_rng(2026112712)
for key,rs in out.items():
 hr=int(key.split('/')[1])
 if not(sum(v['wallet']['30']['terminal_jpy']>10000 for v in rs.values())>=2 or key in ('BEAR_REV72/24','BEAR_MOM72/24','BEAR_REV72/48','BEAR_MOM72/48')):continue
 for per,rec in rs.items():
  pairs=[]
  for x,n in tapes[key][per]:
   side=1 if x['direction']=='LONG' else -1
   aa=[z for a in snaps[(x['entryTs'],n)] if a['symbol']!=x['symbol'] and (z:=trade(a,side,hr)) is not None]
   if len(aa)>=1:pairs.append((x,aa))
  aw=compact(bt.wallet([x for x,a in pairs],per,30,ms));ds=[compact(bt.wallet([a[rng.integers(len(a))] for x,a in pairs],per,30,ms)) for _ in range(32)];vals=[d['terminal_jpy'] for d in ds]
  rec['matched']={'n_pairs':len(pairs),'actual':aw,'mean_terminal':float(np.mean(vals)),'mean_dd':float(np.mean([d['max_dd_pct'] for d in ds])),'beats':sum(aw['terminal_jpy']>v for v in vals),'delta_pp':float(np.mean([100*(x['rawReturn']-np.mean([z['rawReturn'] for z in a])) for x,a in pairs])) if pairs else None,'draws':ds}
  print('MATCH',key,per,len(pairs),round(aw['terminal_jpy']),round(np.mean(vals)),rec['matched']['beats'],rec['matched']['delta_pp'],flush=True)
O.write_text(json.dumps({'protocol':p,'protocol_sha256':hashlib.sha256(P.read_bytes()).hexdigest(),'coverage':{k:dict(v) for k,v in coverage.items()},'results':out,'intentions':{k:[{**x,'side':d,'beta_h':n} for x,d,n in v] for k,v in signals.items()}},indent=2,allow_nan=False),encoding='utf8')
print('SAVED',hashlib.sha256(O.read_bytes()).hexdigest(),flush=True)
